  assert.deepEqual(parseEuros('12.5'), { ok: true, value: 1250 });
  assert.deepEqual(parseEuros('1,234.56'), { ok: true, value: 123456 });
  assert.deepEqual(parseEuros('12.345'), { ok: false, error: 'AMOUNT_INVALID' });
  assert.deepEqual(parseEuros('abc'), { ok: false, error: 'AMOUNT_INVALID' });
});

test('RATES has correct values', () => {
  assert.equal(RATES.EUR, 1);
  assert.equal(RATES.USD, 1.085);
  assert.equal(RATES.GBP, 0.8425);
});

test('convert: EUR to EUR', () => {
  const result = convert(100, 'EUR');
  assert.equal(result.ok, true);
  assert.equal(result.value, 100);
});

test('convert: EUR to USD', () => {
  const result = convert(100, 'USD');
  // 100 EUR cents * 1.085 = 108.5 USD cents → 109 (banker's rounding: 108.5 → 108)
  assert.equal(result.ok, true);
  assert.equal(result.value, 109);
});

test('convert: EUR to GBP', () => {
  const result = convert(100, 'GBP');
  // 100 EUR cents * 0.8425 = 84.25 GBP cents → 84 (banker's rounding: 84.25 → 84)
  assert.equal(result.ok, true);
  assert.equal(result.value, 84);
});

test('convert: large amount EUR to USD', () => {
  const result = convert(123456, 'USD');
  // 123456 * 1.085 = 133879.36 → 133879
  assert.equal(result.ok, true);
  assert.equal(result.value, 133879);
});

test('convert: small amount EUR to GBP', () => {
  const result = convert(50, 'GBP');
  // 50 * 0.8425 = 42.125 → 42
  assert.equal(result.ok, true);
  assert.equal(result.value, 42);
});

test('convert: zero amount', () => {
  assert.deepEqual(convert(0, 'EUR'), { ok: true, value: 0 });
  assert.deepEqual(convert(0, 'USD'), { ok: true, value: 0 });
  assert.deepEqual(convert(0, 'GBP'), { ok: true, value: 0 });
});

test('convert: unknown currency', () => {
  const result = convert(100, 'JPY');
  assert.deepEqual(result, { ok: false, error: 'UNKNOWN_CURRENCY' });
});

test('convert: case sensitive currency', () => {
  const result = convert(100, 'eur');
  assert.deepEqual(result, { ok: false, error: 'UNKNOWN_CURRENCY' });
});

test('formatMoney: EUR format', () => {
  assert.equal(formatMoney(123456, 'EUR'), '€1,234.56');
  assert.equal(formatMoney(5, 'EUR'), '€0.05');
  assert.equal(formatMoney(-250, 'EUR'), '-€2.50');
});

test('formatMoney: USD format', () => {
  assert.equal(formatMoney(123456, 'USD'), '$1,234.56');
  assert.equal(formatMoney(5, 'USD'), '$0.05');
  assert.equal(formatMoney(-250, 'USD'), '-$2.50');
});

test('formatMoney: GBP format', () => {
  assert.equal(formatMoney(123456, 'GBP'), '£1,234.56');
  assert.equal(formatMoney(5, 'GBP'), '£0.05');
  assert.equal(formatMoney(-250, 'GBP'), '-£2.50');
});

test('formatMoney: large amounts', () => {
  assert.equal(formatMoney(100000000, 'EUR'), '€1,000,000.00');
  assert.equal(formatMoney(100000000, 'USD'), '$1,000,000.00');
  assert.equal(formatMoney(100000000, 'GBP'), '£1,000,000.00');
});

test('formatMoney: single digit cents', () => {
  assert.equal(formatMoney(5, 'EUR'), '€0.05');
  assert.equal(formatMoney(5, 'USD'), '$0.05');
  assert.equal(formatMoney(5, 'GBP'), '£0.05');
});

test('formatMoney: zero amount', () => {
  assert.equal(formatMoney(0, 'EUR'), '€0.00');
  assert.equal(formatMoney(0, 'USD'), '$0.00');
  assert.equal(formatMoney(0, 'GBP'), '£0.00');
});

test('formatMoney: unknown currency', () => {
  // Should still format but with unknown symbol
  const result = formatMoney(100, 'JPY');
  assert.equal(result, '?1.00');
});

test('convert and formatMoney together', () => {
  const eurCents = 100;
  const converted = convert(eurCents, 'USD');
  assert.equal(converted.ok, true);
  const formatted = formatMoney(converted.value, 'USD');
  assert(formatted.includes('$'));
  assert(formatted.includes('.'));
});

test('convert rounding precision', () => {
  // Test that rounding works correctly
  const result = convert(1000, 'USD');
  // 1000 * 1.085 = 1085.0
  assert.equal(result.value, 1085);
});

test('convert multiple currencies roundtrip', () => {
  const original = 50000;
  const usd = convert(original, 'USD');
  const gbp = convert(original, 'GBP');

  assert.equal(usd.ok, true);
  assert.equal(gbp.ok, true);
  assert(usd.value > original); // USD rate > 1
  assert(gbp.value < original); // GBP rate < 1
});

test('formatMoney preserves thousands separators', () => {
  const result = formatMoney(1234567, 'EUR');
  assert.equal(result, '€12,345.67');
});

test('formatMoney with different currencies same amount', () => {
  const cents = 100000;
  const eur = formatMoney(cents, 'EUR');
  const usd = formatMoney(cents, 'USD');
  const gbp = formatMoney(cents, 'GBP');

  assert(eur.includes('€'));
  assert(usd.includes('$'));
  assert(gbp.includes('£'));
  assert.equal(eur, '€1,000.00');
  assert.equal(usd, '$1,000.00');
  assert.equal(gbp, '£1,000.00');
});

